    int e = errno;
    free(path_cstr);
    if (rc != 0) {
        z_t3908_t* boxed = (z_t3908_t*)z_xmalloc(sizeof(z_t3908_t));
        *boxed = z_io_errno_to_IoError(e);
        result.tag = Z_RESULT_BOX_FILESTAT_IOERROR_TAG_ERR;
        result.data = boxed;
        return result;
    }
    z_t4141_t fs = {0};
    z_io_fill_filestat(&fs, &sb);
    z_t4141_t* boxed = (z_t4141_t*)z_xmalloc(sizeof(z_t4141_t));
    *boxed = fs;
    result.tag = Z_RESULT_BOX_FILESTAT_IOERROR_TAG_OK;
    result.data = boxed;
    return result;
